-- Migration: Add image_url to investment_plan and seed default SVG base64 codes

-- 1. Add image_url column
ALTER TABLE investment_plan ADD COLUMN IF NOT EXISTS image_url TEXT;

-- 2. Seed lightweight Base64 SVG cards for standard tiers if null
-- Starter: Sleek Emerald Chip Pattern
UPDATE investment_plan 
SET image_url = 'data:image/svg+xml;base64,'
WHERE id = 1 AND image_url IS NULL;

-- Silver: Sleek Cyber Silver Laser Grid
UPDATE investment_plan 
SET image_url = 'data:image/svg+xml;base64,'
WHERE id = 2 AND image_url IS NULL;

-- Gold: Premium Gold Matrix Glow
UPDATE investment_plan 
SET image_url = 'data:image/svg+xml;base64,'
WHERE id = 3 AND image_url IS NULL;
